# Look and feel: header (with dark mode toggle), footer, favicon and the static
# assets in inst/www (fonts, CSS, colour-mode script).
#
# The assets are a thin layer over teal's default Bootstrap 5 theme: they
# redefine Bootstrap's CSS variables instead of compiling a custom theme, so
# start-up needs no Sass compilation and the app stays recognisably teal.
# Everything is served by the app itself: no fonts or icons are fetched from
# third-party servers.

#' Folder with the static assets
#' @noRd
teal_neue_www <- function() {
  path <- system.file("www", package = "teal.neue")
  if (!nzchar(path) || !file.exists(file.path(path, "teal_neue.css"))) {
    stop("[teal_neue] Static assets not found (inst/www). Reinstall the package.", call. = FALSE)
  }
  path
}

#' @noRd
teal_neue_version <- function() as.character(utils::packageVersion("teal.neue"))

#' HTML dependency: fonts, stylesheet and script (colour mode, motion)
#'
#' The inline `head` script runs before the first paint and applies dark mode
#' early (saved choice, app default, or OS preference), so dark-mode users do
#' not see a white flash, and applies the appearance chosen in the app (text
#' size, spacing, accent, ...) and the motion setting; teal_neue.js (loaded
#' with `defer`, so it never delays the first paint) does the rest.
#' @noRd
teal_neue_dependency <- function(color_mode = teal_neue_color_mode(), motion = teal_neue_motion()) {
  htmltools::htmlDependency(
    name = "teal-neue",
    version = teal_neue_version(),
    src = c(file = teal_neue_www()),
    stylesheet = "teal_neue.css",
    script = list(src = "teal_neue.js", defer = NA),
    head = teal_neue_head_script(color_mode, motion),
    all_files = TRUE
  )
}

#' @noRd
teal_neue_head_script <- function(color_mode = teal_neue_color_mode(), motion = teal_neue_motion()) {
  paste0(
    "<script>",
    "window.tealNeue={colorMode:", jsonlite::toJSON(color_mode, auto_unbox = TRUE),
    ",motion:", if (isTRUE(motion)) "true" else "false", "};",
    if (!isTRUE(motion)) "document.documentElement.classList.add('tn-still');",
    # appearance chosen in the app (text size, spacing, accent, ...)
    "try{var r=document.documentElement,",
    "a=JSON.parse(window.localStorage.getItem('teal_neue:appearance')||'{}')||{},",
    "k={text:'data-tn-text',density:'data-tn-density',accent:'data-tn-accent',",
    "corners:'data-tn-corners',contrast:'data-tn-contrast',canvas:'data-tn-canvas'};",
    "for(var x in k){if(a[x]){r.setAttribute(k[x],a[x]);}}",
    "if(a.motion==='off'){r.classList.add('tn-still');}if(a.motion==='on'){r.classList.remove('tn-still');}",
    "}catch(e){}",
    "(function(){var m=null;",
    "try{m=window.localStorage.getItem('teal_neue:color-mode');}catch(e){}",
    "if(m!=='dark'&&m!=='light'&&m!=='auto'){m=window.tealNeue.colorMode;}",
    "if(m==='dark'||(m==='auto'&&window.matchMedia&&",
    "window.matchMedia('(prefers-color-scheme: dark)').matches)){",
    "document.documentElement.setAttribute('data-bs-theme','dark');}",
    "})();",
    "</script>"
  )
}

#' Favicon as a data URI (no request to an external server)
#' @noRd
teal_neue_favicon <- function() {
  path <- file.path(teal_neue_www(), "favicon.png")
  paste0("data:image/png;base64,", jsonlite::base64_enc(readBin(path, "raw", file.size(path))))
}

#' Inline SVG logo
#' @noRd
teal_neue_logo <- function() {
  svg <- paste(readLines(file.path(teal_neue_www(), "logo.svg"), warn = FALSE), collapse = "\n")
  svg <- sub("<svg ", "<svg class=\"tn-logo\" aria-hidden=\"true\" focusable=\"false\" ", svg, fixed = TRUE)
  htmltools::HTML(svg)
}

#' Short description of the data, shown as a badge in the header
#' @param source Resolved source settings (see teal_neue_source_config()).
#' @param n_subjects Number of subjects (rows of ADSL).
#' @noRd
teal_neue_data_label <- function(source, n_subjects = NULL) {
  what <- switch(source$source,
    bundled = "random.cdisc.data (bundled)",
    synthetic = sprintf("Synthetic data, seed %s", source$synthetic$seed),
    parquet = sprintf("Parquet: %s", basename(source$parquet_dir))
  )
  if (!is.null(n_subjects)) what <- sprintf("%s \u00b7 %s subjects", what, format(n_subjects, big.mark = ","))
  what
}

#' App header
#'
#' One row: brand (a link to the home page); the breadcrumb of the current module (filled in by
#' teal_neue.js); the command button (opens the command bar: jump to any
#' module or TLG output, run actions), the data status (source, number of
#' subjects, time of the last update), the appearance button and the
#' colour-mode toggle. The module index for the command bar travels with it
#' as JSON.
#'
#' The colour mode starts in the user's last choice, else the app default
#' (option `teal_neue.color_mode`), else the operating-system preference.
#' Plots are rendered server-side as light images and stay white "paper" in
#' dark mode, so the app matches its R code.
#' @param data_label Text of the data status (NULL: none), e.g.
#'   "random.cdisc.data (bundled) \u00b7 400 subjects"; the part after the
#'   last " \u00b7 " is shown as a figure.
#' @param style Use the teal_neue look (option `teal_neue.style`)? `FALSE`
#'   gives the plain teal header.
#' @param index Module index for the command bar (see teal_neue_index());
#'   NULL: the command bar indexes the tabs it finds on the page.
#' @noRd
teal_neue_header <- function(data_label = NULL, style = teal_neue_style_enabled(), index = NULL) {
  toggle <- bslib::input_dark_mode(id = "teal_neue_dark_mode", mode = NULL)

  if (!isTRUE(style)) {
    return(teal_neue_header_plain(toggle))
  }

  header <- htmltools::tags$header(
    class = "tn-header",
    htmltools::tags$a(
      class = "tn-brand", href = "#/", `data-tn-action` = "home",
      title = "Home (H)", `aria-label` = "teal_neue, go to the home page",
      teal_neue_logo(),
      htmltools::div(
        class = "tn-titles",
        htmltools::span(class = "tn-title", htmltools::HTML("teal<span class=\"tn-title-accent\">_neue</span>")),
        htmltools::span(class = "tn-subtitle", "Clinical Trial Analysis")
      )
    ),
    htmltools::tags$nav(class = "tn-crumbs", `aria-label` = "Current module"),
    htmltools::div(
      class = "tn-actions",
      htmltools::tags$button(
        type = "button", class = "tn-cmd", `data-tn-action` = "palette",
        `aria-label` = "Jump to a module, an output or an action", `aria-keyshortcuts` = "Control+K Meta+K",
        teal_neue_icon("search"),
        htmltools::span(class = "tn-cmd-label", "Jump to module, output, action\u2026"),
        htmltools::tags$kbd(class = "tn-cmd-key", "Ctrl K")
      ),
      if (!is.null(data_label)) teal_neue_status(data_label),
      htmltools::tags$button(
        type = "button", class = "tn-iconbtn", `data-tn-action` = "appearance",
        `aria-haspopup` = "dialog", `aria-expanded` = "false",
        title = "Appearance (A)", `aria-label` = "Appearance: text size, spacing, accent and more",
        teal_neue_icon("density")
      ),
      htmltools::span(class = "tn-toggle", title = "Light / dark (T)", toggle)
    ),
    if (!is.null(index)) {
      htmltools::tags$script(
        type = "application/json", id = "tn-index",
        htmltools::HTML(gsub("</", "<\\/", jsonlite::toJSON(index, auto_unbox = TRUE, na = "null", null = "null"), fixed = TRUE))
      )
    }
  )
  htmltools::attachDependencies(header, teal_neue_dependency(), append = TRUE)
}

#' Data status of the header: a live dot (amber while the server computes),
#' the source, the number of subjects as a figure and the duration of the
#' last update (filled in by teal_neue.js)
#' @noRd
teal_neue_status <- function(data_label) {
  parts <- strsplit(data_label, " \u00b7 ", fixed = TRUE)[[1]]
  figure <- if (length(parts) > 1) parts[length(parts)] else NULL
  source <- paste(if (is.null(figure)) parts else parts[-length(parts)], collapse = " \u00b7 ")
  htmltools::span(
    class = "tn-status", title = paste("Data:", data_label), role = "status",
    htmltools::span(class = "tn-status-dot", `aria-hidden` = "true"),
    htmltools::span(class = "tn-status-source", source),
    if (!is.null(figure)) {
      htmltools::span(
        class = "tn-status-figure",
        htmltools::span(class = "tn-status-num", sub(" .*$", "", figure)),
        " ",
        htmltools::span(class = "tn-status-unit", sub("^\\S+\\s*", "", figure))
      )
    },
    htmltools::span(class = "tn-status-time")
  )
}

#' Module index for the command bar
#'
#' One entry per module (its path of group labels and its kind, for the
#' icon) and one per TLG Catalog output (ID, title, type, topic). The command
#' bar finds the matching tabs on the page; the index gives it the order,
#' the kinds and the outputs.
#' @param modules The app's teal modules (see teal_neue_modules()).
#' @param catalog TLG Catalog entries (see tlg_catalog()).
#' @param overview Study overview for the home page (see
#'   teal_neue_overview()), or `NULL`.
#' @noRd
teal_neue_index <- function(modules, catalog = tlg_catalog(), overview = NULL) {
  walk <- function(x, path) {
    if (inherits(x, "teal_modules")) {
      here <- if (length(path) || !identical(x$label, "root")) c(path, x$label) else path
      unlist(lapply(x$children, walk, path = here), recursive = FALSE)
    } else {
      list(list(path = c(path, x$label), kind = teal_neue_module_kind(x$label, path)))
    }
  }
  # the top-level modules() call is the root; its label is not shown
  entries <- if (inherits(modules, "teal_modules")) {
    unlist(lapply(modules$children, walk, path = character(0)), recursive = FALSE)
  } else {
    walk(modules, character(0))
  }
  out <- list(
    modules = lapply(entries, function(e) list(path = as.list(e$path), kind = e$kind)),
    tlg = unname(lapply(catalog, function(e) list(id = e$id, title = e$title, type = e$type, topic = e$topic)))
  )
  if (!is.null(overview)) out$overview <- overview
  out
}

#' Kind of a module, for its icon in the command bar
#' @noRd
teal_neue_module_kind <- function(label, path = character(0)) {
  l <- tolower(label)
  if ("TLG Catalog" %in% path) return("catalog")
  if (l %in% c("app info")) return("info")
  if (grepl("data table|variable browser|file viewer", l)) return("data")
  if (grepl("plot|forest|kaplan|scatter|bivariate|association|\\bregression\\b|distribution|outlier|pca|missing", l)) {
    return("graph")
  }
  "table"
}

#' Plain header (option teal_neue.style = FALSE): title and toggle, with the
#' minimal dark-mode fixes of the original app
#' @noRd
teal_neue_header_plain <- function(toggle) {
  dark_mode_css <- htmltools::tags$style(htmltools::HTML("
    [data-bs-theme='dark'] .shiny-plot-output img {
      background-color: #fff;
      border-radius: 0.5rem;
      padding: 0.25rem;
    }
    [data-bs-theme='dark'] table { color: var(--bs-body-color); }
  "))
  htmltools::tags$span(
    style = "display: flex; align-items: center; justify-content: space-between; margin: 10px 0 10px 0;",
    dark_mode_css,
    htmltools::tags$span("teal_neue: Clinical Trial Analysis", style = "font-size: 30px;"),
    htmltools::tags$span(
      style = "display: flex; align-items: center; gap: 8px;",
      htmltools::tags$span("Dark mode", class = "text-body-secondary", style = "font-size: 14px;"),
      toggle
    )
  )
}

#' App footer
#' @noRd
teal_neue_footer <- function(style = teal_neue_style_enabled()) {
  gallery_source <- "https://github.com/insightsengineering/teal.gallery/tree/main"
  link <- function(href, text) htmltools::tags$a(href = href, target = "_blank", rel = "noopener", text)
  sep <- function() htmltools::span(class = "tn-sep", `aria-hidden` = "true", "\u00b7")

  credits <- htmltools::span(
    "Built with the open-source ", link("https://insightsengineering.github.io/teal/", "teal"),
    " framework, based on the teal.gallery templates: ",
    link(file.path(gallery_source, "exploratory"), "Exploratory"), sep(),
    link(file.path(gallery_source, "safety"), "Safety"), sep(),
    link(file.path(gallery_source, "efficacy"), "Efficacy")
  )
  if (!isTRUE(style)) {
    return(htmltools::tags$p(credits))
  }
  htmltools::div(
    class = "tn-footer",
    credits,
    htmltools::span(
      class = "tn-footer-keys",
      htmltools::span(htmltools::tags$kbd("Ctrl K"), " jump"),
      htmltools::span(htmltools::tags$kbd("?"), " shortcuts")
    ),
    htmltools::span(class = "tn-version", paste("teal_neue", teal_neue_version()))
  )
}

#' teal_neue options
#'
#' All settings are regular R options. Set them before building the app (or
#' pass the equivalent arguments to [run_app()] / [load_teal_neue_data()]).
#'
#' @section Data source:
#' \describe{
#'   \item{`teal_neue.data_source`}{`"bundled"` (default), `"synthetic"` or
#'     `"parquet"`. See [ingest_adam()].}
#'   \item{`teal_neue.synthetic`}{Settings for the `"synthetic"` source:
#'     `list(N = 400, seed = 2025, args = list())`. `N` is the number of
#'     subjects; change `seed` for a new draw (`NA` draws a random seed once per
#'     session); `args` holds extra arguments per dataset for the
#'     `random.cdisc.data::rad*()` generators, e.g.
#'     `list(ADAE = list(max_n_aes = 5))`.}
#'   \item{`teal_neue.parquet_dir`}{Folder read by the `"parquet"` source
#'     (default `"cache"`).}
#' }
#'
#' @section Caching:
#' \describe{
#'   \item{`teal_neue.use_cache`}{Use the session memory and disk caches
#'     (default `TRUE`).}
#'   \item{`teal_neue.refresh_cache`}{Force re-ingestion and re-processing
#'     (default `FALSE`).}
#'   \item{`teal_neue.cache_global`}{Copy every dataset (`ADSL`, `ADAE`, ...) into
#'     the Global Environment for easy console access (default `FALSE`;
#'     [run_app()] turns it on).}
#'   \item{`teal_neue.app_cache`}{Keep the built app in memory for the R
#'     session and reuse it when [run_app()] is called again with the same
#'     settings and data (instant relaunch), and serve the app's page from
#'     memory after the first request (default `TRUE`).}
#'   \item{`teal_neue.cache_dir`}{Folder of the disk cache (default
#'     `tools::R_user_dir("teal.neue", "cache")`).}
#' }
#'
#' @section Look and feel:
#' \describe{
#'   \item{`teal_neue.style`}{Use the teal_neue look and its interactive
#'     layer: the header with the breadcrumb and command bar (Ctrl/Cmd+K),
#'     keyboard shortcuts, deep links, plot and table tools, pins and the
#'     viewer, refined light and dark palettes, self-hosted fonts and cleaner
#'     plot defaults (default `TRUE`). `FALSE` gives the plain teal look of
#'     the source templates.}
#'   \item{`teal_neue.motion`}{Animations (default `TRUE`): short
#'     transitions, the sliding tab indicator, the colour-mode reveal. `FALSE`
#'     turns them off; they are also off for users who ask their system for
#'     reduced motion.}
#'   \item{`teal_neue.color_mode`}{Colour mode for first-time visitors:
#'     `"light"` (default), `"dark"` or `"auto"` (follows the operating
#'     system). A choice made with the header toggle is remembered by the
#'     browser and takes precedence.}
#'   \item{`teal_neue.ggtheme`}{Default ggplot2 theme of the exploratory plot
#'     modules (default `"minimal"`; any of `"gray"`, `"bw"`, `"linedraw"`,
#'     `"light"`, `"dark"`, `"minimal"`, `"classic"`). Users can still change it
#'     in each module. `NULL` keeps each module's own default.}
#' }
#'
#' The app also sets two options of its building blocks, only if you have not
#' set them yourself: `teal.ggplot2_args` (plot captions and typography, see
#' [teal_neue_ggplot2_args()]) and `shiny.useragg` (`FALSE`, as in the
#' teal.gallery templates).
#'
#' @examples
#' \dontrun{
#' options(teal_neue.data_source = "synthetic", teal_neue.synthetic = list(N = 200, seed = 7))
#' options(teal_neue.color_mode = "dark")
#' run_app()
#' }
#' @name teal_neue_options
NULL

teal_neue_cache_dir_default <- function() {
  getOption("teal_neue.cache_dir", tools::R_user_dir("teal.neue", which = "cache"))
}

#' @noRd
teal_neue_style_enabled <- function(style = getOption("teal_neue.style", TRUE)) {
  if (!(isTRUE(style) || isFALSE(style))) {
    stop("[teal_neue] Option teal_neue.style must be TRUE or FALSE.", call. = FALSE)
  }
  style
}

#' @noRd
teal_neue_color_mode <- function(mode = getOption("teal_neue.color_mode", "light")) {
  modes <- c("auto", "light", "dark")
  if (!(is.character(mode) && length(mode) == 1 && mode %in% modes)) {
    stop("[teal_neue] Option teal_neue.color_mode must be one of: ", toString(dQuote(modes, FALSE)), call. = FALSE)
  }
  mode
}

#' @noRd
teal_neue_motion <- function(motion = getOption("teal_neue.motion", TRUE)) {
  if (!(isTRUE(motion) || isFALSE(motion))) {
    stop("[teal_neue] Option teal_neue.motion must be TRUE or FALSE.", call. = FALSE)
  }
  motion
}

#' @noRd
teal_neue_ggtheme <- function(ggtheme = getOption("teal_neue.ggtheme", "minimal")) {
  themes <- c("gray", "bw", "linedraw", "light", "dark", "minimal", "classic", "void")
  if (!is.null(ggtheme) && !(is.character(ggtheme) && length(ggtheme) == 1 && ggtheme %in% themes)) {
    stop("[teal_neue] Option teal_neue.ggtheme must be NULL or one of: ", toString(dQuote(themes, FALSE)), call. = FALSE)
  }
  ggtheme
}

# Study overview for the home page: a compact summary of demographics,
# safety and efficacy, computed once when the app is built and rendered by
# teal_neue.js as widgets on the App Info page (see inst/www/teal_neue.js,
# "Overview").
#
# It describes the whole study (no filters): a fixed point of reference. The
# modules remain the place for filtered, reproducible analyses; each widget
# links to the module that goes into detail. Every part is optional: if a
# dataset or variable is missing (e.g. parquet data from another study), that
# part is left out and the others are still shown.

#' Study overview of the app's data, with links to the matching modules
#' @param data The app's `teal_data`.
#' @param modules The app's modules (for the link targets).
#' @noRd
teal_neue_app_overview <- function(data, modules) {
  get <- function(name) tryCatch(data[[name]], error = function(e) NULL)
  labels <- leaf_labels(modules)
  pick <- function(pattern) {
    hit <- grep(pattern, labels, value = TRUE, ignore.case = TRUE)
    if (length(hit)) hit[[1]]
  }
  tryCatch(
    teal_neue_overview(
      get("ADSL"), get("ADAE"), get("ADTTE"), get("ADRS"),
      links = list(
        demographics = pick("^demographic"),
        safety = pick("^ae summary$|adverse event.*summary"),
        efficacy = pick("kaplan"),
        response = pick("^response table$")
      )
    ),
    error = function(e) NULL
  )
}

#' Study overview for the home page
#'
#' @param adsl,adae,adtte,adrs Analysis datasets (`ADAE`, `ADTTE` and `ADRS`
#'   may be `NULL`).
#' @param links Module labels the widgets link to (named: `demographics`,
#'   `safety`, `efficacy`, `response`); `NULL` entries are left out.
#' @return A list ready for JSON: `population`, `demographics`, `safety`,
#'   `efficacy` (each may be `NULL`) and `links`.
#' @noRd
teal_neue_overview <- function(adsl, adae = NULL, adtte = NULL, adrs = NULL, links = list()) {
  part <- function(expr) tryCatch(expr, error = function(e) NULL)
  adsl <- as.data.frame(adsl)
  arm_var <- overview_arm_var(adsl)
  arms <- overview_levels(adsl[[arm_var]])
  list(
    population = part(overview_population(adsl, arm_var, arms)),
    demographics = part(overview_demographics(adsl, arm_var, arms)),
    safety = if (!is.null(adae)) part(overview_safety(adsl, as.data.frame(adae), arm_var, arms)),
    efficacy = part(overview_efficacy(adsl, adtte, adrs, arm_var, arms)),
    links = Filter(Negate(is.null), links)
  )
}

#' "BLACK OR AFRICAN AMERICAN" -> "Black or African American" (for labels
#' stored in capitals; fast, unlike tools::toTitleCase())
#' @noRd
overview_title_case <- function(x) {
  small <- c("or", "of", "and", "the", "in", "to")
  x <- as.character(x)
  out <- vapply(strsplit(tolower(x), " ", fixed = TRUE), function(w) {
    cap <- !(w %in% small) | seq_along(w) == 1
    w[cap] <- paste0(toupper(substr(w[cap], 1, 1)), substr(w[cap], 2, nchar(w[cap])))
    paste(w, collapse = " ")
  }, character(1))
  out[is.na(x)] <- NA_character_
  out
}

#' @noRd
overview_arm_var <- function(adsl) {
  hit <- intersect(c("ARM", "ACTARM", "TRT01P", "TRT01A"), names(adsl))
  if (!length(hit)) stop("no arm variable")
  hit[[1]]
}

#' @noRd
overview_levels <- function(x) {
  if (is.factor(x)) {
    lv <- levels(droplevels(x))
  } else {
    lv <- sort(unique(as.character(x)))
  }
  lv[!is.na(lv) & nzchar(lv)]
}

#' Share in percent, one decimal
#' @noRd
overview_pct <- function(n, total) if (total > 0) round(100 * n / total, 1) else 0

#' @noRd
overview_population <- function(adsl, arm_var, arms) {
  n_arm <- vapply(arms, function(a) sum(adsl[[arm_var]] == a, na.rm = TRUE), numeric(1))
  list(
    n = nrow(adsl),
    arms = lapply(seq_along(arms), function(i) list(name = arms[[i]], n = n_arm[[i]])),
    countries = if ("COUNTRY" %in% names(adsl)) length(unique(stats::na.omit(as.character(adsl$COUNTRY))))
  )
}

#' @noRd
overview_demographics <- function(adsl, arm_var, arms) {
  out <- list()
  if ("AGE" %in% names(adsl)) {
    age <- adsl$AGE[!is.na(adsl$AGE)]
    q <- stats::quantile(age, c(.25, .5, .75), names = FALSE)
    width <- 5
    lo <- floor(min(age) / width) * width
    hi <- ceiling((max(age) + 1) / width) * width
    breaks <- seq(lo, hi, by = width)
    counts <- as.integer(table(cut(age, breaks, right = FALSE)))
    out$age <- list(
      median = round(q[2], 1), q1 = round(q[1], 1), q3 = round(q[3], 1),
      min = min(age), max = max(age),
      bins = lapply(seq_along(counts), function(i) list(from = breaks[i], to = breaks[i + 1], n = counts[[i]])),
      by_arm = lapply(arms, function(a) {
        x <- adsl$AGE[adsl[[arm_var]] == a & !is.na(adsl$AGE)]
        list(arm = a, median = if (length(x)) round(stats::median(x), 1) else NA_real_)
      })
    )
  }
  count_levels <- function(x, top = Inf) {
    x <- as.character(x)
    x <- x[!is.na(x) & nzchar(x)]
    tab <- sort(table(x), decreasing = TRUE)
    keep <- utils::head(tab, top)
    rest <- sum(tab) - sum(keep)
    res <- lapply(names(keep), function(k) list(level = k, n = as.integer(keep[[k]]), pct = overview_pct(keep[[k]], length(x))))
    if (rest > 0) res <- c(res, list(list(level = "Other", n = as.integer(rest), pct = overview_pct(rest, length(x)))))
    res
  }
  if ("SEX" %in% names(adsl)) out$sex <- count_levels(adsl$SEX)
  if ("RACE" %in% names(adsl)) out$race <- count_levels(overview_title_case(adsl$RACE), top = 4)
  if ("COUNTRY" %in% names(adsl)) out$country <- count_levels(adsl$COUNTRY, top = 5)
  out
}

#' Safety summary on the safety population (SAFFL = "Y" when available):
#' subjects with an event, per arm, for a few key categories, and the most
#' frequent preferred terms
#' @noRd
overview_safety <- function(adsl, adae, arm_var, arms) {
  pop <- if ("SAFFL" %in% names(adsl)) adsl[adsl$SAFFL %in% "Y", , drop = FALSE] else adsl
  if (!nrow(pop)) stop("empty safety population")
  ae <- adae[adae$USUBJID %in% pop$USUBJID, , drop = FALSE]
  if ("TRTEMFL" %in% names(ae) && any(ae$TRTEMFL %in% "Y")) ae <- ae[ae$TRTEMFL %in% "Y", , drop = FALSE]
  arm_of <- stats::setNames(as.character(pop[[arm_var]]), pop$USUBJID)
  n_arm <- vapply(arms, function(a) sum(arm_of == a, na.rm = TRUE), numeric(1))

  by_arm <- function(subjects) {
    subjects <- unique(subjects)
    lapply(seq_along(arms), function(i) {
      n <- sum(arm_of[subjects] == arms[[i]], na.rm = TRUE)
      list(n = n, pct = overview_pct(n, n_arm[[i]]))
    })
  }
  metric <- function(id, label, subjects) list(id = id, label = label, by_arm = by_arm(subjects))
  metrics <- list(metric("any", "Any adverse event", ae$USUBJID))
  if ("AESER" %in% names(ae)) metrics <- c(metrics, list(metric("serious", "Serious", ae$USUBJID[ae$AESER %in% "Y"])))
  if ("AETOXGR" %in% names(ae)) {
    grade <- suppressWarnings(as.numeric(as.character(ae$AETOXGR)))
    metrics <- c(metrics, list(metric("grade3", "Grade \u2265 3", ae$USUBJID[!is.na(grade) & grade >= 3])))
  }
  if ("AEACN" %in% names(ae)) {
    metrics <- c(metrics, list(metric("withdrawn", "Led to withdrawal", ae$USUBJID[ae$AEACN %in% "DRUG WITHDRAWN"])))
  }
  if ("DTHFL" %in% names(pop)) {
    metrics <- c(metrics, list(metric("death", "Deaths", pop$USUBJID[pop$DTHFL %in% "Y"])))
  }

  terms <- NULL
  if ("AEDECOD" %in% names(ae)) {
    subj_term <- unique(ae[!is.na(ae$AEDECOD), c("USUBJID", "AEDECOD")])
    tab <- sort(table(as.character(subj_term$AEDECOD)), decreasing = TRUE)
    top <- names(utils::head(tab, 5))
    terms <- lapply(top, function(term) {
      subj <- subj_term$USUBJID[subj_term$AEDECOD == term]
      list(term = term, n = length(unique(subj)), pct = overview_pct(length(unique(subj)), nrow(pop)), by_arm = by_arm(subj))
    })
  }
  list(
    population = if ("SAFFL" %in% names(adsl)) "Safety population" else "All subjects",
    n = nrow(pop),
    n_by_arm = as.list(unname(n_arm)),
    metrics = metrics,
    terms = terms
  )
}

#' Kaplan-Meier (product-limit) estimate, as a step curve
#' @param time,event Follow-up time and event indicator (1 = event).
#' @return `list(curve = list(c(t, s), ...), median, n, events)`; at most
#'   `max_points` points, keeping every drop large enough to be visible.
#' @noRd
overview_km <- function(time, event, max_points = 80L) {
  ok <- !is.na(time) & !is.na(event)
  time <- time[ok]
  event <- event[ok]
  n <- length(time)
  if (!n) return(NULL)
  ev_times <- sort(unique(time[event == 1]))
  s <- 1
  pts <- list(c(0, 1))
  median <- NULL
  for (t in ev_times) {
    at_risk <- sum(time >= t)
    d <- sum(time == t & event == 1)
    s <- s * (1 - d / at_risk)
    pts[[length(pts) + 1]] <- c(t, s)
    if (is.null(median) && s <= .5) median <- t
  }
  pts[[length(pts) + 1]] <- c(max(time), s)
  if (length(pts) > max_points) {
    keep <- unique(round(seq(1, length(pts), length.out = max_points)))
    pts <- pts[keep]
  }
  list(
    curve = lapply(pts, function(p) round(p, 4)),
    median = if (!is.null(median)) round(median, 1) else NA_real_,
    n = n,
    events = sum(event == 1)
  )
}

#' Wilson score interval for a proportion, in percent
#' @noRd
overview_wilson <- function(x, n, z = 1.959964) {
  if (!n) return(c(NA_real_, NA_real_))
  p <- x / n
  den <- 1 + z^2 / n
  centre <- (p + z^2 / (2 * n)) / den
  half <- z * sqrt(p * (1 - p) / n + z^2 / (4 * n^2)) / den
  round(100 * c(max(0, centre - half), min(1, centre + half)), 1)
}

#' Efficacy summary on the intent-to-treat population (ITTFL = "Y" when
#' available): overall survival by arm and best overall response rate
#' @noRd
overview_efficacy <- function(adsl, adtte, adrs, arm_var, arms) {
  pop <- if ("ITTFL" %in% names(adsl)) adsl[adsl$ITTFL %in% "Y", , drop = FALSE] else adsl
  arm_of <- stats::setNames(as.character(pop[[arm_var]]), pop$USUBJID)
  out <- list(population = if ("ITTFL" %in% names(adsl)) "Intent-to-treat population" else "All subjects")

  if (!is.null(adtte)) {
    tte <- as.data.frame(adtte)
    params <- unique(as.character(tte$PARAMCD))
    param <- intersect(c("OS", "PFS", "EFS"), params)[1]
    if (!is.na(param) && all(c("AVAL", "CNSR") %in% names(tte))) {
      x <- tte[tte$PARAMCD == param & tte$USUBJID %in% pop$USUBJID, , drop = FALSE]
      label <- if ("PARAM" %in% names(x) && nrow(x)) as.character(x$PARAM[1]) else param
      unit <- if ("AVALU" %in% names(x) && nrow(x)) tolower(as.character(x$AVALU[1])) else ""
      all <- overview_km(x$AVAL, 1 - x$CNSR)
      out$survival <- list(
        param = param, label = label, unit = unit,
        overall = list(median = all$median, n = all$n, events = all$events),
        arms = lapply(arms, function(a) {
          y <- x[arm_of[x$USUBJID] %in% a, , drop = FALSE]
          km <- overview_km(y$AVAL, 1 - y$CNSR)
          c(list(arm = a), km)
        })
      )
    }
  }

  if (!is.null(adrs)) {
    rs <- as.data.frame(adrs)
    param <- intersect(c("BESRSPI", "BESRSP", "OVRINV"), unique(as.character(rs$PARAMCD)))[1]
    if (!is.na(param) && "AVALC" %in% names(rs)) {
      x <- rs[rs$PARAMCD == param & rs$USUBJID %in% pop$USUBJID, , drop = FALSE]
      x <- x[!duplicated(x$USUBJID), , drop = FALSE]
      label <- if ("PARAM" %in% names(x) && nrow(x)) as.character(x$PARAM[1]) else param
      out$response <- list(
        param = param, label = label, definition = "CR or PR",
        arms = lapply(arms, function(a) {
          y <- x[arm_of[x$USUBJID] %in% a, , drop = FALSE]
          r <- sum(y$AVALC %in% c("CR", "PR"))
          ci <- overview_wilson(r, nrow(y))
          list(arm = a, n = nrow(y), responders = r, pct = overview_pct(r, nrow(y)), lo = ci[1], hi = ci[2])
        })
      )
    }
  }
  if (is.null(out$survival) && is.null(out$response)) NULL else out
}

# TLG Catalog: every output of the TLG Catalog
# (https://insightsengineering.github.io/tlg-catalog/stable/tlg-index.html),
# organised in one page per topic (Adverse Events, Concomitant Medications,
# ...), each with a selector of its tables, listings and graphs.
#
# Each output is a registry entry (see tlg()) whose R code is a plain string,
# evaluated with teal's eval_code() on the module's *filtered* data. The same
# string is shown under "Show R code", so every output is reproducible. The
# code follows the catalog (same packages: tern, rtables, rlistings,
# tern.mmrm), adapted to this app's datasets. A failing output shows its error
# and code; it never breaks the page.
#
# Entries live in R/tlg_entries_*.R, one function per group of topics.

# ---- Registry ---------------------------------------------------------------

#' Topics (pages) of the TLG Catalog, in menu order
#' @noRd
tlg_topics <- function() {
  c(
    "Adverse Events", "Concomitant Medications", "Deaths", "Demography",
    "Disclosures", "Disposition", "ECG", "Efficacy", "Exposure", "Lab Results",
    "Medical History", "Pharmacokinetics", "Anti-Drug Antibodies",
    "Risk Management Plan", "Vital Signs", "Other Graphs"
  )
}

#' Define one catalog output
#' @param id Catalog identifier, e.g. "AET01".
#' @param title Catalog title.
#' @param type "Table", "Listing" or "Graph".
#' @param topic Page (one of tlg_topics()).
#' @param slug Catalog folder of the output (for the link to the catalog page).
#' @param data App datasets the code uses (filtered by the app).
#' @param extra Extra example datasets from 'random.cdisc.data' (see
#'   tlg_example_data()), e.g. "ADPC".
#' @param packages Packages the code needs.
#' @param code R code (string) that creates `result`.
#' @param note Optional note shown with the output (e.g. how it was adapted).
#' @param height Plot height in pixels (graphs).
#' @noRd
tlg <- function(id, title, type = c("Table", "Listing", "Graph"), topic, slug,
                data = "ADSL", extra = character(0), packages = NULL, code,
                note = NULL, height = 560L) {
  type <- match.arg(type)
  if (is.null(packages)) {
    packages <- switch(type,
      Table = "tern",
      Listing = c("tern", "rlistings"),
      Graph = c("tern", "ggplot2")
    )
  }
  list(
    id = id, title = title, type = type, topic = topic, slug = slug,
    data = data, extra = extra, packages = packages,
    code = trimws(code), note = note, height = as.integer(height)
  )
}

#' All catalog entries, named by id
#'
#' The registry is fixed for a package version, so it is built once per R
#' session and then served from memory.
#' @noRd
tlg_catalog <- function() {
  cached <- get0("tlg_catalog", envir = the, inherits = FALSE)
  if (!is.null(cached)) return(cached)
  catalog <- tlg_catalog_build()
  assign("tlg_catalog", catalog, envir = the)
  catalog
}

#' @noRd
tlg_catalog_build <- function() {
  entries <- c(
    tlg_entries_adverse_events(),
    tlg_entries_conmed(),
    tlg_entries_deaths_demography(),
    tlg_entries_disclosures_disposition(),
    tlg_entries_ecg(),
    tlg_entries_efficacy(),
    tlg_entries_exposure_rmp(),
    tlg_entries_lab(),
    tlg_entries_medical_history(),
    tlg_entries_pk(),
    tlg_entries_ada(),
    tlg_entries_vital_signs(),
    tlg_entries_other_graphs()
  )
  stats::setNames(entries, vapply(entries, `[[`, character(1), "id"))
}

#' Entries of one topic, tables first, then listings, then graphs
#' @noRd
tlg_topic_entries <- function(topic, catalog = tlg_catalog()) {
  entries <- Filter(function(e) identical(e$topic, topic), catalog)
  type_order <- match(vapply(entries, `[[`, character(1), "type"), c("Table", "Listing", "Graph"))
  entries[order(type_order, seq_along(entries))]
}

#' Link to the output's page in the TLG Catalog
#' @noRd
tlg_catalog_url <- function(entry) {
  base <- "https://insightsengineering.github.io/tlg-catalog/stable"
  folder <- switch(entry$type, Table = "tables", Listing = "listings", Graph = "graphs")
  sprintf("%s/%s/%s/%s.html", base, folder, entry$slug, tolower(entry$id))
}

#' Example data for outputs that need datasets the app does not load
#'
#' Some catalog outputs need datasets that are not part of the app's data
#' (e.g. `ADPC`, `ADPP`, `ADAB`, `ADMH`, `ADHY`). `tlg_example_data()` returns
#' the synthetic version bundled with 'random.cdisc.data' (`cadpc`, ...),
#' restricted to the subjects of `adsl` so that the app's filters apply. If
#' none of the subjects match (e.g. with your own study data), the full
#' example dataset is returned.
#'
#' @param dataset Dataset name, e.g. `"ADPC"`.
#' @param adsl Subject-level data whose subjects to keep (optional).
#' @return A data.frame.
#' @examples
#' \donttest{
#' adpc <- tlg_example_data("ADPC")
#' }
#' @export
tlg_example_data <- function(dataset, adsl = NULL) {
  name <- paste0("c", tolower(dataset))
  df <- tryCatch(
    getExportedValue("random.cdisc.data", name),
    error = function(e) stop("[teal_neue] 'random.cdisc.data' has no dataset ", sQuote(name, FALSE), call. = FALSE)
  )
  if (!is.null(adsl) && "USUBJID" %in% names(df) && "USUBJID" %in% names(adsl)) {
    keep <- as.character(df$USUBJID) %in% as.character(adsl$USUBJID)
    if (any(keep)) df <- dplyr::filter(df, keep)
  }
  df
}

# ---- Running and rendering ----------------------------------------------------

#' Run one catalog entry on a teal_data object
#' @return list(ok, kind, value, error, seconds)
#' @noRd
tlg_run <- function(entry, data) {
  missing_pkgs <- entry$packages[!vapply(entry$packages, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing_pkgs)) {
    return(list(
      ok = FALSE, kind = "missing",
      error = sprintf("This output needs the package%s %s, which %s not installed.",
                      if (length(missing_pkgs) > 1) "s" else "",
                      paste(sQuote(missing_pkgs, FALSE), collapse = ", "),
                      if (length(missing_pkgs) > 1) "are" else "is")
    ))
  }
  t0 <- Sys.time()
  q <- tryCatch(
    suppressWarnings(suppressMessages(teal.code::eval_code(data, entry$code))),
    error = function(e) e
  )
  seconds <- as.numeric(difftime(Sys.time(), t0, units = "secs"))
  if (inherits(q, c("qenv.error", "error"))) {
    return(list(ok = FALSE, kind = "error", error = conditionMessage(q), seconds = seconds))
  }
  value <- tryCatch(q[["result"]], error = function(e) NULL)
  if (is.null(value)) {
    return(list(ok = FALSE, kind = "error", error = "The code did not create an object called `result`.", seconds = seconds))
  }
  list(ok = TRUE, kind = tlg_kind(value), value = value, seconds = seconds)
}

#' Kind of output object: table, listing, plot, data or text
#' @noRd
tlg_kind <- function(x) {
  if (inherits(x, "VTableTree")) return("table")
  if (inherits(x, "listing_df")) return("listing")
  if (inherits(x, c("ggplot", "gg", "grob", "gtable", "gTree", "trellis", "recordedplot"))) return("plot")
  if (is.data.frame(x)) return("data")
  "text"
}

#' Draw a plot object (ggplot, grid grob/gtable, lattice)
#' @noRd
tlg_draw <- function(x) {
  if (inherits(x, c("ggplot", "gg", "trellis", "recordedplot"))) {
    print(x)
  } else {
    grid::grid.newpage()
    grid::grid.draw(x)
  }
  invisible()
}

#' Column labels of a data.frame (label attribute, else the name)
#' @noRd
tlg_labels <- function(df) {
  vapply(names(df), function(n) {
    l <- attr(df[[n]], "label", exact = TRUE)
    if (is.null(l) || !nzchar(l)) n else as.character(l)[1]
  }, character(1), USE.NAMES = FALSE)
}

#' Listing or data.frame as an interactive table
#' @noRd
tlg_datatable <- function(x) {
  df <- as.data.frame(x)
  cols <- names(df)
  if (inherits(x, "listing_df")) {
    shown <- tryCatch(
      c(rlistings::get_keycols(x), rlistings::listing_dispcols(x)),
      error = function(e) cols
    )
    cols <- unique(intersect(shown, cols))
    if (!length(cols)) cols <- names(df)
  }
  df <- df[cols]
  DT::datatable(
    df,
    colnames = tlg_labels(df),
    rownames = FALSE,
    class = "compact hover",
    options = list(pageLength = 25, scrollX = TRUE, autoWidth = FALSE, dom = "ftip")
  )
}

# ---- Module -------------------------------------------------------------------

#' TLG Catalog module group: one page per topic
#' @param datanames Datasets available in the app.
#' @noRd
modules_tlg_catalog <- function(datanames, catalog = tlg_catalog()) {
  pages <- lapply(tlg_topics(), function(topic) {
    tm_tlg_catalog(topic, entries = tlg_topic_entries(topic, catalog), datanames = datanames)
  })
  do.call(modules, c(list(label = "TLG Catalog"), pages))
}

#' One TLG Catalog page
#' @noRd
tm_tlg_catalog <- function(topic, entries, datanames) {
  used <- unique(unlist(lapply(entries, `[[`, "data")))
  module(
    label = topic,
    server = srv_tlg_catalog,
    ui = ui_tlg_catalog,
    ui_args = list(topic = topic, entries = entries),
    server_args = list(entries = entries),
    datanames = intersect(union("ADSL", used), datanames)
  )
}

#' Static assets of the TLG Catalog pages (always loaded, with or without
#' the teal_neue style)
#' @noRd
tlg_catalog_dependency <- function() {
  htmltools::htmlDependency(
    name = "teal-neue-tlg",
    version = teal_neue_version(),
    src = c(file = teal_neue_www()),
    stylesheet = "tlg_catalog.css",
    script = "tlg_catalog.js",
    all_files = FALSE
  )
}

#' @noRd
tlg_count_label <- function(entries) {
  types <- vapply(entries, `[[`, character(1), "type")
  parts <- vapply(c("Table", "Listing", "Graph"), function(t) {
    n <- sum(types == t)
    if (!n) return(NA_character_)
    sprintf("%d %s%s", n, tolower(t), if (n > 1) "s" else "")
  }, character(1))
  paste(stats::na.omit(parts), collapse = " \u00b7 ")
}

#' Icons for the TLG Catalog pages
#'
#' Thin line icons in the style of SF Symbols (16 px grid, stroked with the
#' current text colour).
#' @param name Icon name: "Table", "Listing", "Graph", "code", "external",
#'   "search", "warning", "data" or "density".
#' @noRd
teal_neue_icon <- function(name) {
  paths <- switch(name,
    Table = '<rect x="2" y="3" width="12" height="10" rx="2"/><path d="M2 6.5h12M6.5 6.5V13"/>',
    Listing = '<path d="M6 4.5h8M6 8h8M6 11.5h8"/><circle cx="2.8" cy="4.5" r=".6"/><circle cx="2.8" cy="8" r=".6"/><circle cx="2.8" cy="11.5" r=".6"/>',
    Graph = '<path d="M2.5 13.5h11"/><path d="M4.5 11V8M8 11V4.5M11.5 11V6.5"/>',
    code = '<path d="M5.5 4.5 2 8l3.5 3.5M10.5 4.5 14 8l-3.5 3.5"/>',
    external = '<path d="M6 3.5H3.5v9h9V10"/><path d="M9 2.5h4.5V7M13.5 2.5 7.5 8.5"/>',
    search = '<circle cx="7" cy="7" r="4.5"/><path d="m10.5 10.5 3 3"/>',
    warning = '<path d="M8 2.5 14 13H2L8 2.5Z"/><path d="M8 6.5v3"/><circle cx="8" cy="11.2" r=".5"/>',
    data = '<ellipse cx="8" cy="4" rx="5" ry="2"/><path d="M3 4v8c0 1.1 2.2 2 5 2s5-.9 5-2V4M3 8c0 1.1 2.2 2 5 2s5-.9 5-2"/>',
    density = '<path d="M2.5 4h11M2.5 8h11M2.5 12h11"/><path d="M5 2.5v3M11 6.5v3M7 10.5v3"/>',
    ""
  )
  htmltools::HTML(paste0(
    '<svg class="tn-icon" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" ',
    'stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">',
    paths, "</svg>"
  ))
}

