        ),
        htmltools::tags$section(
          class = "tn-tlg-main",
          shiny::uiOutput(ns("header")),
          htmltools::div(class = "tn-tlg-output", shiny::uiOutput(ns("output")))
        )
      )
    )
  )
}

#' @noRd
srv_tlg_catalog <- function(id, data, entries) {
  shiny::moduleServer(id, function(input, output, session) {
    ns <- session$ns

    selected <- shiny::reactive({
      chosen <- input$tlg
      if (is.null(chosen) || !chosen %in% names(entries)) names(entries)[1] else chosen
    })
    entry <- shiny::reactive(entries[[selected()]])

    # Results are cached per output and thrown away when the (filtered) data
    # change, so switching back and forth between outputs is instant.
    cache <- new.env(parent = emptyenv())
    cached_for <- NULL
    result <- shiny::reactive({
      d <- data()
      if (!identical(cached_for, d)) {
        rm(list = ls(cache, all.names = TRUE), envir = cache)
        cached_for <<- d
      }
      e <- entry()
      if (is.null(cache[[e$id]])) cache[[e$id]] <- tlg_run(e, d)
      cache[[e$id]]
    })

    output$header <- shiny::renderUI({
      e <- entry()
      htmltools::tags$header(
        class = "tn-tlg-toolbar",
        htmltools::div(
          class = "tn-tlg-title-block",
          htmltools::div(
            class = "tn-tlg-meta",
            htmltools::span(class = "tn-tlg-chip tn-tlg-chip-id", e$id),
            htmltools::span(class = paste0("tn-tlg-chip tn-tlg-chip-", tolower(e$type)), teal_neue_icon(e$type), e$type)
          ),
          htmltools::h3(class = "tn-tlg-title", e$title),
          if (!is.null(e$note)) htmltools::p(class = "tn-tlg-note", e$note)
        ),
        htmltools::div(
          class = "tn-tlg-actions",
          shiny::actionButton(ns("show_code"), label = htmltools::tagList(teal_neue_icon("code"), "Show R code"), class = "tn-tlg-action"),
          htmltools::tags$a(
            class = "btn btn-default tn-tlg-action", href = tlg_catalog_url(e),
            target = "_blank", rel = "noopener", title = "Open this output in the TLG Catalog",
            teal_neue_icon("external"), "Catalog"
          )
        )
      )
    })

    output$output <- shiny::renderUI({
      res <- result()
      e <- entry()
      if (!isTRUE(res$ok)) {
        missing <- identical(res$kind, "missing")
        return(htmltools::div(
          class = paste("tn-tlg-message", if (missing) "tn-tlg-message-info" else "tn-tlg-message-error"),
          htmltools::div(class = "tn-tlg-message-icon", teal_neue_icon("warning")),
          htmltools::h4(if (missing) "Package needed" else "This output could not be produced with the current data"),
          htmltools::p(res$error),
          htmltools::p(class = "tn-tlg-message-hint", "Use \u201cShow R code\u201d to inspect the code, or open the catalog page for the reference version.")
        ))
      }
      switch(res$kind,
        table = htmltools::div(class = "tn-tlg-scroll tn-tlg-rtable", rtables::as_html(res$value)),
        listing = DT::DTOutput(ns("listing")),
        data = DT::DTOutput(ns("listing")),
        plot = shiny::plotOutput(ns("plot"), height = paste0(e$height, "px")),
        htmltools::tags$pre(paste(utils::capture.output(print(res$value)), collapse = "\n"))
      )
    })

    output$listing <- DT::renderDT({
      res <- result()
      shiny::req(isTRUE(res$ok), res$kind %in% c("listing", "data"))
      tlg_datatable(res$value)
    })

    output$plot <- shiny::renderPlot({
      res <- result()
      shiny::req(isTRUE(res$ok), identical(res$kind, "plot"))
      tlg_draw(res$value)
    }, res = 96)

    shiny::observeEvent(input$show_code, {
      e <- entry()
      code <- paste(c(teal.code::get_code(data()), "", paste0("# ---- ", e$id, ": ", e$title, " ----"), e$code), collapse = "\n")
      code_id <- ns("code_text")
      shiny::showModal(shiny::modalDialog(
        title = paste0(e$id, " \u00b7 R code"),
        size = "l", easyClose = TRUE,
        htmltools::tags$pre(
          class = "tn-tlg-code", .noWS = c("after-begin", "before-end"),
          htmltools::tags$code(id = code_id, code, .noWS = c("outside", "inside"))
        ),
        footer = htmltools::tagList(
          htmltools::tags$button(
            type = "button", class = "btn btn-default",
            onclick = sprintf(
              "navigator.clipboard && navigator.clipboard.writeText(document.getElementById('%s').innerText); this.innerText = 'Copied';",
              code_id
            ),
            "Copy"
          ),
          htmltools::tags$button(
            type = "button", class = "btn btn-primary",
            `data-dismiss` = "modal", `data-bs-dismiss` = "modal", "Done"
          )
        )
      ))
    })
  })
}

/*
 * teal_neue: "Instrument", a look for teal built for people who read
 * clinical data all day.
 *
 * Ideas
 *   - A precision instrument, not a poster: white, hairline-ruled panels on
 *     a faint dot-grid canvas (lab-notebook paper); colour only where it
 *     means something (teal = where you are / what acts, amber = working).
 *   - Two voices: Inter (or the system font on Apple devices) for reading,
 *     JetBrains Mono for machine facts (dataset and variable names, output
 *     IDs, counts, timings, keys, section labels).
 *   - Fast by construction: no background images, no blur, no ambient
 *     animation; transitions are 120-260 ms and only on transform, opacity
 *     and colours.
 *   - Keyboard first: the command bar (Cmd/Ctrl+K) reaches every module and
 *     every TLG output; the breadcrumb shows where you are; see
 *     teal_neue.js for the behaviour.
 *
 * Nothing is moved: teal's structure and Bootstrap 5 theme stay (bslib's
 * precompiled CSS, so there is no Sass compilation at start-up). This file
 * redefines Bootstrap's CSS custom properties and restyles standard
 * Bootstrap / bslib / Shiny components, and styles the elements that
 * teal_neue adds (header, command bar, tools, toasts).
 *
 * Sections
 *   1. Fonts              2. Tokens (scale, light, dark, density)
 *   3. Canvas and type    4. Header (brand, breadcrumb, command button,
 *                            status) and footer
 *   5. Navigation         6. Controls      7. Surfaces
 *   8. Menus and sheets   9. Data (tables, code, plots)
 *  10. Feedback          11. teal_neue layers (command bar, shortcut sheet,
 *                            plot viewer, hover tools, toasts, focus mode)
 *  12. Motion            13. Dark-mode fixes
 *  14. TLG Catalog pages
 */

/* 1. Fonts ------------------------------------------------------------------ */
/* Apple devices use the system font (SF Pro): nothing is downloaded. Elsewhere
   Inter (one 92 KB variable file, every weight), served by the app. There is
   no italic file on purpose: icon tags (<i>) would make browsers download it
   on every page. */

@font-face {
  font-family: "Inter";
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
  src: url("fonts/InterVariable.woff2") format("woff2");
}
@font-face {
  font-family: "JetBrains Mono";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("fonts/JetBrainsMonoNL-Regular.woff2") format("woff2");
}
@font-face {
  font-family: "JetBrains Mono";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("fonts/JetBrainsMonoNL-Bold.woff2") format("woff2");
}

/* 2. Tokens ------------------------------------------------------------------ */

/* Mode-independent. `html:root` outranks Bootstrap's `:root` whatever the
   stylesheet order. */
html:root {
  --tn-font-sans: -apple-system, BlinkMacSystemFont, "Inter", "Segoe UI Variable Text", "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --tn-font-mono: "JetBrains Mono", ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;

  /* type scale (px) and tracking (Inter's size-dependent metrics) */
  --tn-fs-2xs: .6875rem;  /* 11 */
  --tn-fs-xs: .75rem;     /* 12 */
  --tn-fs-sm: .8125rem;   /* 13 */
  --tn-fs-md: .875rem;    /* 14 */
  --tn-fs-lg: 1rem;       /* 16 */
  --tn-fs-xl: 1.25rem;    /* 20 */
  --tn-fs-2xl: 1.625rem;  /* 26 */
  --tn-track-tight: -.018em;
  --tn-track: -.006em;
  --tn-track-mono: .02em;
  --tn-track-caps: .08em;

  /* 4 px grid */
  --tn-s1: 4px; --tn-s2: 8px; --tn-s3: 12px; --tn-s4: 16px; --tn-s5: 20px; --tn-s6: 24px; --tn-s8: 32px;
  --tn-r-sm: 6px;
  --tn-r: 8px;
  --tn-r-lg: 12px;
  --tn-r-xl: 14px;
  --tn-control-h: 34px;
  --tn-cell: .5rem .7rem;

  /* motion: short, and only on cheap properties */
  --tn-ease: cubic-bezier(.2, .8, .2, 1);
  --tn-fast: 120ms;
  --tn-med: 200ms;
  --tn-slow: 260ms;

  --bs-font-sans-serif: var(--tn-font-sans);
  --bs-body-font-family: var(--tn-font-sans);
  --bs-font-monospace: var(--tn-font-mono);
  --bs-body-font-size: var(--tn-fs-md);
  --bs-body-line-height: 1.5;
  --bs-border-radius: var(--tn-r);
  --bs-border-radius-sm: var(--tn-r-sm);
  --bs-border-radius-lg: var(--tn-r-lg);
  --bs-border-radius-xl: var(--tn-r-xl);
  --bs-border-radius-pill: 999px;

  /* Shiny's own busy indicators are replaced by teal_neue's progress line */
  --shiny-pulse-background: transparent;
  --shiny-pulse-height: 0px;
  --shiny-spinner-color: var(--tn-accent);
}

